        untrusted.update(claimed - previous - captured_by_note.get(rel, set()))
    captured = {key for values in captured_by_note.values() for key in values}
    # 另一篇合法安家不能替本篇的途中假宣告作證;不确定时只撤回補助路由。
    candidates = (possible & (old | captured)) - untrusted
    read = _nodehome_reader(repo_root, tree, from_git=True)
    config = read(".lumos/config.json")
    if config is None and ".lumos/config.json" in all_paths:
        return set()
    cfg = _nodehome_config(repo_root, config, from_snapshot=True)
    skip = frozenset() if _is_toolchain_repo(repo_root) else _vendored_state(repo_root, tree)[0]
    routes = _nodehome_route_tests(repo_root, files, all_paths, candidates, tree, cfg, skip, reader=read)
    old_read = _nodehome_reader(repo_root, B.where, from_git=True)
    old_config = old_read(".lumos/config.json")
